def extend_pricing(pages, locale):
    t = lambda en, ko: ko if locale == 'ko' else en
    customer = '<h2>' + t('Find the discount on your products and instances', '내 제품·인스턴스의 할인율 찾기') + '</h2>'
    customer += '<div class="auto-form"><label>' + t('Product / instance name or ID', '제품 / 인스턴스명 또는 ID') + '<input value="rds-prod-01"></label><label>' + t('Billing period / document state', '청구 기간 / 문서 상태') + '<input value="2026-10 · ' + t('Estimate', '예상') + '"></label></div>'
    customer += '<table><thead><tr>' + ''.join('<th>'+x+'</th>' for x in [t('Instance / product','인스턴스 / 제품'),t('Usage × basis rate','사용량 × 기준 요율'),t('Contract discount','계약 할인율'),t('Discount / applied rate','할인액 / 적용 요율'),t('Charge · USD','청구액 · USD')]) + '</tr></thead><tbody><tr><td>rds-prod-01<br>DEMO-CUSTOMER-INSTANCE-01 · DB compute</td><td>100 h × USD 10.00/h<br>USD 1,000.00</td><td>10%<br>' + t('Applied', '적용됨') + '</td><td>−USD 100.00<br>USD 9.00/h</td><td>900.00</td></tr></tbody></table>'
    customer += '<p>' + t('Search result: 1 instance · USD 900.00 pretax. Whole-month estimate above remains USD 1,535.00; filtering never recalculates discounts. Illustrative quantity/rate breakdown of the same DB charge, not verified provider pricing.', '검색 결과: 인스턴스 1개 · 세전 USD 900.00. 상단 월 전체 예상액 USD 1,535.00과 별도이며 검색으로 할인을 재계산하지 않습니다. 동일 DB 비용을 설명하는 합성 수량·단가이며 실제 공급자 가격이 아닙니다.') + '</p>'
    customer += '<p class="auto-note">' + t('Selected detail: contract discount 10%; effective discount 10% against the same USD 1,000 basis in this example (no credits). Extra sales discount excluded because the product discount already applies. Scope: DB compute only, not storage/backup/IO. Selling terms effective for October; estimate, not issued. On issued bills, show the frozen document/version. No instance attribution, no discount, excluded and pending calculation are distinct states. Flat/credit/tiered prices show their formula; no invented percentage.', '선택 상세: 계약 할인율 10% · 동일 기준액 USD 1,000 대비 실효 할인율 10%(이 예시에는 크레딧 없음). 제품 할인이 적용되어 영업 추가 할인은 제외됩니다. DB 사용료만 적용하며 스토리지·백업·IO는 제외됩니다. 10월 적용 판매 조건의 예상액이며 발행 전입니다. 발행 문서는 당시 문서·버전을 표시합니다. 인스턴스 귀속 없음·할인 없음·제외·계산 대기는 구분합니다. 정액·크레딧·구간 요율은 산식을 표시하고 임의 할인율로 바꾸지 않습니다.') + '</p>'
    pages['auto-customer'] += customer
    pages['auto-portfolio'] += '<h2>' + t('Verify pricing by product and instance', '제품·인스턴스별 요율 적용 확인') + '</h2><p>' + t('Within an authorized customer, search product, instance name/ID and month. Show applied, no discount, excluded, pending and blocked results with reasons. Every charge retains its basis, effective customer terms, quantity, unit rate, discount and final amount; shared/unattributed charges remain visible.', '권한 있는 고객 범위에서 제품·인스턴스명/ID·월로 조회합니다. 적용·할인 없음·제외·대기·보류를 사유와 함께 표시합니다. 비용별 기준액·적용 고객 계약·수량·단가·할인율·할인액·최종 금액을 보존하고 공통·미귀속 비용도 남깁니다.') + '</p><p><a href="#auto-trace">' + t('Inspect instance pricing evidence', '인스턴스 요율 근거 확인') + ' →</a></p>'
    pages['auto-trace'] += '<h2>' + t('Selected instance evidence', '선택 인스턴스 계산 근거') + '</h2><p>DEMO-DB-01 · rds-prod-01 · 100 h × USD 10.00/h = USD 1,000.00 → 10% (−USD 100.00) → USD 9.00/h × 100 h = USD 900.00.</p><p class="auto-note">' + t('Synthetic subdivision of the DB charge above; source revision and usage period remain pinned. Instance name is a display label, not the matching identity. Do not invent resource attribution for DTO/shared fees. Customer disclosure includes approved selling evidence only; operator cost/margin and internal identifiers remain restricted.', '위 DB 비용의 합성 수량·단가 상세이며 원천 버전·사용 기간은 고정됩니다. 인스턴스명은 표시용이며 매칭 식별자가 아닙니다. DTO·공통 비용의 리소스 귀속을 임의로 만들지 않습니다. 고객에게는 공개 승인된 판매 근거만 보여주며 운영자 원가·마진·내부 식별자는 제한합니다.') + '</p>'
    return pages
